import{_ as t,a as s,a3 as o,o as a}from"./chunks/framework.yJBLK5ap.js";const p=JSON.parse('{"title":"WsSQL2 quick start","description":"","frontmatter":{},"headers":[],"relativePath":"esp/services/ws_sql2/README.md","filePath":"esp/services/ws_sql2/README.md","lastUpdated":1795797312000}'),i={name:"esp/services/ws_sql2/README.md"};function c(d,e,r,n,l,h){return a(),s("div",null,[...e[0]||(e[0]=[o(`<h1 id="wssql2-quick-start" tabindex="-1">WsSQL2 quick start <a class="header-anchor" href="#wssql2-quick-start" aria-label="Permalink to &quot;WsSQL2 quick start&quot;">​</a></h1><p>Run these commands from the repository root. The examples assume the build directory is <code>./build</code>, with WsSQL2 and CppUnit enabled.</p><h2 id="build" tabindex="-1">Build <a class="header-anchor" href="#build" aria-label="Permalink to &quot;Build&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cmake</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --build</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --target</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ws_sql2</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --parallel</span></span></code></pre></div><p>The <code>duckdb-hpcc/</code> sources are compiled into <code>ws_sql2</code>; they do not produce a separate shared library.</p><h2 id="deploy" tabindex="-1">Deploy <a class="header-anchor" href="#deploy" aria-label="Permalink to &quot;Deploy&quot;">​</a></h2><p>Install the updated platform and restart the ESP instance hosting WsSQL2 (replace <code>myesp</code> with your ESP instance name):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cmake</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --build</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --target</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --parallel</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/init.d/hpcc-init</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> restart</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> myesp</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># as single command</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cmake</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --build</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --target</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --parallel</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/init.d/hpcc-init</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> restart</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> myesp</span></span></code></pre></div><p><code>ExecuteQuery</code> accepts exactly one read-only <code>SELECT</code> statement; a trailing semicolon is allowed. To run a script that contains several statements, call <code>SplitQuery</code> first and execute each <code>SELECT</code> separately; each one then gets its own independently pageable cursor. <code>SplitQuery</code> only parses <code>SqlText</code> with the same DuckDB parser that <code>ExecuteQuery</code> uses; it does not bind or execute anything, so it reads no logical files. It returns <code>Statements</code>, one string per statement in order: the original source, including comments, without surrounding whitespace or the terminating semicolon. Statements other than <code>SELECT</code> are returned rather than rejected; <code>ExecuteQuery</code> rejects them if they are run. Empty or whitespace-only text returns no statements. If any statement has a syntax error, the request fails.</p><p><code>ExecuteQuery</code> parses, binds, and plans the query without running it, and returns an opaque <code>CursorId</code>, <code>InitMs</code>, <code>PrepareMs</code>, and (when requested) <code>ResultSetMetadata</code>. The query runs when the first <code>FetchResultSet</code> is called, so runtime errors are reported by that fetch. Each <code>FetchResultSet</code> returns a JSON row batch in <code>RowsJSON</code>, <code>ExecuteMs</code> (server-side time spent producing that batch), and <code>Complete</code>, which is <code>true</code> once the server has observed end-of-stream. <code>RowCount</code> on <code>FetchResultSet</code> is the requested batch size; zero (the default) uses the configured <code>defaultFetchSize</code> (1000 unless configured), and requests are capped at <code>maxFetchSize</code> (10000 by default). <code>maxByteLimit</code> caps each response batch in bytes (64 MiB by default); zero means unlimited. The service enforces <code>maxActiveCursors</code> (100) and <code>maxCursorsPerUser</code> (10), and expires idle cursors after <code>cursorIdleTimeoutSeconds</code> (300) or any cursor after <code>cursorMaxLifetimeSeconds</code> (3600).</p><p>A batch that fills exactly retains its cursor without a read-ahead; the next fetch may therefore be empty with <code>Complete</code> set. When a batch observes end-of-stream, the server releases the DuckDB query and its spill resources immediately, and the <code>CursorId</code> is no longer valid. <code>CloseResultSet</code> releases an unfinished cursor at any point, including while a fetch is running: the running query is interrupted and that fetch fails with error code <code>20001</code> (<code>QueryCancelled</code>). <code>CloseResultSet</code> never fails: <code>Closed</code> is <code>true</code> when the call released an open cursor, and <code>false</code> when there was nothing to close because the cursor already completed, failed, expired, or was closed, or the ID is unknown or owned by another user. Clients can therefore always call it during cleanup. A cursor that reaches <code>cursorMaxLifetimeSeconds</code> is cancelled the same way and an in-flight fetch fails with code <code>20002</code> (<code>QueryLifetimeExceeded</code>); both codes are declared by the <code>WsSQL2ErrorCode</code> enum in <code>ws_sql2.ecm</code>. The idle timeout restarts after each fetch that leaves the cursor open, and a cursor with a fetch in progress is never idle; the maximum lifetime counts from <code>ExecuteQuery</code> and never restarts. Each open cursor counts against the cursor limits until it completes or is closed. Cursor IDs are bound to the authenticated user, and concurrent fetches for one cursor are serialized.</p><p>All requests share one DuckDB instance and its spill directory. DuckDB&#39;s internal spill I/O is permitted there, but SQL file functions and SQL file writes are blocked, including within that directory. Configure <code>tempDirectory</code> on disk-backed storage accessible only to the ESP service account; the spill directory is not a per-user boundary.</p><p>Set <code>IncludeResultSetMetadata</code> to return a <code>ResultSetMetadata</code> entry for each output column in the <code>ExecuteQuery</code> response (the column list is known once the query is bound); each entry contains its JDBC-style column label (<code>ColumnLabel</code>), type name (<code>ColumnTypeName</code>), precision, and scale. Precision and scale are zero when unavailable. <code>IncludeRuntimeGraph</code> requests the runtime graph: DuckDB&#39;s profiled query tree as text (<code>RuntimeGraph</code>) and JSON (<code>RuntimeGraphJson</code>), with actual row counts and timings. DuckDB completes the profile at end-of-stream, so both are returned by the <code>FetchResultSet</code> that reports <code>Complete</code>. In the runtime graph, each <code>HPCC_SCAN</code> reports the <code>Keyed Filters</code> and <code>Post Filters</code> chosen when the scan started, so they include filters pushed down at runtime by joins; filters on the same KEY field are intersected into one keyed filter. <code>ExplainQuery</code> returns the optimized static plan, with estimates but no runtime figures, as text (<code>Plan</code>) and JSON (<code>PlanJson</code>), plus result-set metadata, without executing the query. HPCC-specific logical-file details remain under <code>LogicalFileMetadata</code>.</p><p>Set <code>IncludeDebug</code> on <code>ExecuteQuery</code> to have each <code>FetchResultSet</code> return a <code>DebugInfo</code> struct reporting memory usage and checking for leaks. Each <code>MemoryUsage</code> snapshot has DuckDB buffer-manager memory and spill (<code>DuckDBUsedBytes</code>, <code>DuckDBTempBytes</code>), the bytes allocated through malloc (<code>HeapInUseBytes</code>, from jemalloc when it is preloaded, otherwise glibc), and process resident memory (<code>ResidentBytes</code>, <code>PeakResidentBytes</code>). <code>Start</code> is taken in <code>ExecuteQuery</code> before the query&#39;s engine is created and <code>Current</code> after the batch is produced. Once end-of-stream is observed, the engine is released and <code>Released</code> is reported, along with <code>Retained</code> (<code>Released</code> minus <code>Start</code>). <code>LeakCheck</code> is then <code>Passed</code>, or <code>PossibleLeak</code> if DuckDB or heap memory grew by more than the <code>leakCheckThresholdBytes</code> service setting (default 1048576, 1 MiB). One-time initialization can cause growth on first use, so repeat the query to confirm. These figures are instance- and process-wide, so if any other query engine existed during the measurement window the result is <code>Inconclusive</code>. A cursor left open reports <code>Pending</code>; it carries the setting forward, and the final <code>FetchResultSet</code> returns the verdict.</p><p>Debug builds (<code>_DEBUG</code>) also count the <code>hpcc_scan</code> objects each engine creates and destroys: bind data, global states and local states. These counts are returned as <code>ScanObjectsCreated</code> and <code>ScanObjectsLive</code>. The counts belong to the query&#39;s engine, so they are exact even when other queries run concurrently. If any of those objects is still live after the engine is released, <code>LeakCheck</code> is <code>Leaked</code>. Release builds omit these fields and use only the memory check.</p><p><code>LogicalFileMetadata</code> accepts a logical file name and returns a <code>LogicalFileMetadata</code> struct. Its fields include the ECL record, physical parts (<code>FileParts</code>), the total <code>RecordCount</code> when Dali has it (otherwise the field is omitted), and each top-level scan option; <code>FormatOptions</code> and <code>ProviderOptions</code> contain JSON objects. When <code>RecordCount</code> is known, <code>SELECT COUNT(*) FROM hpcc_scan(&#39;logical-name&#39;)</code> is answered from metadata without reading file parts. Filtered counts and scans without a known count still execute normally. A client can also use the count returned by <code>LogicalFileMetadata</code> to answer an unfiltered <code>COUNT(*)</code> without fetching rows. <code>SampleSQL</code> contains a query with the record, parts, and options embedded in a long-form <code>hpcc_scan(record, parts, options)</code> call for use by a host that permits the long form; it cannot be executed through WsSQL2. The short-form scan and <code>LogicalFileMetadata</code> reject external and foreign logical names, including compound names containing either, before Dali lookup. The long form reads supplied physical parts without Dali file authorization and is therefore disabled in WsSQL2; it remains available to other hosts of the DuckDB extension. Record layouts that require a compiled helper are not supported in this release.</p><h2 id="decimal-fields" tabindex="-1">Decimal fields <a class="header-anchor" href="#decimal-fields" aria-label="Permalink to &quot;Decimal fields&quot;">​</a></h2><p>HPCC <code>DECIMAL</code> and <code>UDECIMAL</code> fields support widths from 1 through 38, preserving their declared precision and scale. Wider HPCC decimal fields and scales greater than the width are rejected during query binding (<code>ExecuteQuery</code> or <code>ExplainQuery</code>), before a cursor or result-set metadata is returned.</p><h2 id="run-c-unit-tests" tabindex="-1">Run C++ unit tests <a class="header-anchor" href="#run-c-unit-tests" aria-label="Permalink to &quot;Run C++ unit tests&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./build/Debug/bin/unittests</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> WsSql2TypeMappingTests</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> WsSql2MetadataTests</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> WsSql2QueryEngineTests</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -v</span></span></code></pre></div><h2 id="run-python-tests" tabindex="-1">Run Python tests <a class="header-anchor" href="#run-python-tests" aria-label="Permalink to &quot;Run Python tests&quot;">​</a></h2><p>Both scripts test a running WsSQL2 service (default endpoint <code>http://127.0.0.1:8510/WsSQL2/</code>) and require the relevant <code>regress::*</code> logical files to be available. Deploy/start the service and ensure the regression files are present before running them. The <code>dg_var</code> layout is currently expected to return an unsupported-layout error.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./esp/services/ws_sql2/tests/sql-test</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --pq</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 10</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./esp/services/ws_sql2/tests/read-regress.py</span></span></code></pre></div><p>The SQL test runner reads its connection settings from <code>tests/sql-test.json</code> and discovers SQL cases from the <code>sql/</code> and <code>sql-*/</code> directories:</p><ul><li><code>sql/</code> compares query results with JSON files under <code>sql/ExecuteQuery/</code>.</li><li><code>sql-xfail/</code> checks that the query fails (in <code>ExecuteQuery</code> or its first fetch) with the error text specified in <code>ExecuteQuery/</code>.</li><li><code>sql-cursor/</code> checks fetch batches, cursor lifetime, and explicit close behavior, and cancelling a running first fetch with <code>CloseResultSet</code>, using assertions under <code>Cursor/</code>.</li><li><code>sql-equivalence/</code> compares the results of an optimized query with a semantically equivalent residual-filter query, using assertions under <code>Compare/</code>.</li><li><code>sql-metrics/</code> checks query rows and required runtime-graph fields under <code>ExecuteQuery/</code>.</li><li><code>sql-explain/</code> checks optimized-plan text and <code>HPCC_SCAN</code> details returned by <code>ExplainQuery</code>, using assertions under <code>ExplainQuery/</code>.</li><li><code>sql-split/</code> checks the statement text that <code>SplitQuery</code> returns for a multi-statement script, or its expected parse error, using assertions under <code>SplitQuery/</code>. These cases parse SQL without executing it.</li><li><code>sql-ecl/</code> pairs each <code>.sql</code> file with a same-named <code>.ecl</code> file, runs SQL through WsSQL2 and ECL through <code>ecl run</code>, and compares their results&#39; columns (case-insensitively, as ECL lower-cases field names), row order, and values. The SQL file may hold several statements: the runner splits it with <code>SplitQuery</code>, runs each statement in turn, and compares the Nth statement&#39;s result with the ECL workunit&#39;s Nth output Dataset. It reports every mismatched or failed result and any difference in result counts, rather than stopping at the first. Drawing on ECL regression cases, the suite covers ranges, filters, sorts, grouped counts, index and KEY reads (<code>dg_index</code>, <code>dg_keyed_index</code>, <code>searchindex</code>), plus inner, left outer, and anti joins over <code>regress::multi</code> files. The <code>key_*</code> cases check <code>searchindex</code> key pushdown — keyed and payload filters, out-of-range and contradictory bounds, ordered limits, and distinct-key joins — against the equivalent ECL index reads. The <code>search_source_word_counts</code>, <code>search_index_word_counts</code>, and <code>search_source_key_doc_join</code> cases aggregate the multi-million-row <code>searchsource</code> and <code>searchindex</code> files before returning bounded results; they take longer than the small-file cases. Each PASS line reports, in aligned columns, the SQL <code>ExecuteMs</code> summed over every <code>FetchResultSet</code> response (server-side execution, excluding HTTP and query preparation) and the ECL workunit&#39;s <code>TotalClusterTime</code> from <code>WsWorkunits/WUQuery</code> as <code>ECL &lt;time&gt;</code>, with <code>&lt;</code>, <code>&gt;</code>, or <code>=</code> between them showing whether SQL was faster, slower, or equal to the millisecond, followed in parentheses by end-to-end wall-clock times for SQL (the HTTP request, preparation, and fetching every result batch) and ECL (including compilation and result retrieval), again with <code>&lt;</code>, <code>&gt;</code>, or <code>=</code> between them.</li></ul><p>The KEY scan plan cases that declare <code>scanPartsFromLogicalFile</code> call <code>LogicalFileMetadata</code> to derive their expected physical-part and data-part/thread counts (excluding any top-level KEY part). LIMIT/OFFSET pushdown expectations follow the resulting data-part count rather than assuming a fixed layout.</p><p><code>--updateResults</code> refreshes result snapshots for <code>sql/</code> and <code>sql-metrics/</code>; it does not rewrite the behavioral assertions in the other suites. Use <code>--pq N</code> to run SQL cases concurrently without a runner-imposed cap; requesting more parallel queries than the service allows can fail the tests. Override the endpoint with <code>WS_SQL2_ENDPOINT</code> or <code>--server</code>; use <code>--config</code> to provide a different SQL test config file. The runner prints and flushes a <code>START</code> line when each case begins, then reports its <code>PASS</code> or <code>FAIL</code> status and elapsed time when it completes. Parallel cases are reported in completion order, so a started case without a completion line is still running. The runner prints a summary and exits non-zero if any case fails. The catalog test accepts <code>--endpoint</code>, <code>--dfu-endpoint</code> (default <code>http://localhost:8010/WsDfu/DFUQuery.json</code>), <code>--scope</code>, and other options; run it with <code>--help</code> for details. It gets logical-file names from WsDFU. Only when files fail does it write a JSON report listing those failures (<code>read-regress-errors.json</code> by default, override with <code>--report</code>), and a passing run deletes any stale report.</p><p>For <code>sql-ecl/</code>, <code>ecl</code> must be on <code>PATH</code> and the configured ECL service must be available. <code>sql-test.json</code> supplies <code>espIp</code>, <code>espSocket</code>, <code>eclTarget</code>, and optionally <code>eclCluster</code>; <code>--eclTarget</code> and <code>--eclCluster</code> override the target and cluster. The SQL and ECL operations use the configured test user. Once the ECL run returns a WUID, the runner deletes that workunit via <code>WUDelete</code> after comparing results and retrieving the cluster time, including when a case fails. Use an ECL <code>OUTPUT(..., NAMED(&#39;Result&#39;))</code> with field names and ordering matching the SQL projection; ECL XML values are compared to SQL JSON values using SQL&#39;s boolean/numeric types.</p><p>Run only the SQL/ECL comparisons with <code>./esp/services/ws_sql2/tests/sql-test --suite sql-ecl</code>; add a SQL filename after the option to run one paired case. The <code>--suite</code> option works with the other suite directories as well.</p>`,29)])])}const m=t(i,[["render",c]]);export{p as __pageData,m as default};
